import type { MetadataRoute } from "next";

// P2: installable app. The manifest is generated by the framework so the
// link tag lands in the document head automatically. Maskable icon separate
// so Android can fill its shaped launchers without shaving the glyph.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Rah · Your road from B2 to C1",
    short_name: "Rah",
    description:
      "English learning platform for Farsi speakers: FSRS-5 spaced retrieval, a built-in AI coach, writing and speaking labs, listening decoding, and honest measurement.",
    id: "/",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#10131a",
    theme_color: "#10131a",
    categories: ["education"],
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png" },
      { src: "/icons/maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
